import java.util.*;

public class Main {
    static final int MAXNODES = 210;
    static final int MAXEDGES = 1000007;

    static int n, T;
    static char[][] grid1 = new char[15][15];
    static char[][] grid2 = new char[15][15];
    static int[][] node_id = new int[15][15];
    static int total_nodes;
    static int source_node, sink_node;
    static int special_x, special_y;
    static int[][] directions = { {0,1}, {0,-1}, {1,0}, {-1,0} };

    static int[] edges_v = new int[MAXEDGES];
    static int[] edges_cap = new int[MAXEDGES];
    static int[] edges_next = new int[MAXEDGES];
    static int[] head = new int[MAXNODES];
    static int edge_count = 0;
    static int[] parent_node = new int[MAXNODES];
    static int[] visited_node = new int[MAXNODES];

    static boolean is_valid(int x, int y) {
        return x >= 0 && y >= 0 && x < n && y < n && grid1[x][y] >= '0' && grid1[x][y] <= '9';
    }

    static void addEdge(int u, int v, int c) {
        edges_v[edge_count] = v;
        edges_cap[edge_count] = c;
        edges_next[edge_count] = head[u];
        head[u] = edge_count++;
        edges_v[edge_count] = u;
        edges_cap[edge_count] = 0;
        edges_next[edge_count] = head[v];
        head[v] = edge_count++;
    }

    static int maxFlow() {
        int total_flow = 0;
        while (true) {
            Arrays.fill(parent_node, -1);
            Arrays.fill(visited_node, 0);
            Queue<Integer> q = new LinkedList<>();
            q.add(source_node);
            visited_node[source_node] = 1;
            boolean foundSink = false;
            while (!q.isEmpty()) {
                int u = q.poll();
                for (int i = head[u]; i != -1; i = edges_next[i]) {
                    int v = edges_v[i];
                    if (edges_cap[i] > 0 && visited_node[v] == 0) {
                        visited_node[v] = 1;
                        parent_node[v] = i;
                        if (v == sink_node) {
                            foundSink = true;
                            break;
                        }
                        q.add(v);
                    }
                }
                if (foundSink) break;
            }
            if (!foundSink) break;
            int flow = Integer.MAX_VALUE;
            for (int v = sink_node; v != source_node; v = edges_v[parent_node[v] ^ 1]) {
                flow = Math.min(flow, edges_cap[parent_node[v]]);
            }
            for (int v = sink_node; v != source_node; v = edges_v[parent_node[v] ^ 1]) {
                edges_cap[parent_node[v]] -= flow;
                edges_cap[parent_node[v] ^ 1] += flow;
            }
            total_flow += flow;
        }
        return total_flow;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        T = sc.nextInt();
        for (int i = 0; i < n; i++) {
            String line = sc.next();
            for (int j = 0; j < n; j++) {
                grid1[i][j] = line.charAt(j);
            }
        }
        for (int i = 0; i < n; i++) {
            String line = sc.next();
            for (int j = 0; j < n; j++) {
                grid2[i][j] = line.charAt(j);
            }
        }

        Arrays.fill(head, -1);
        edge_count = 0;
        for (int i = 0; i < 15; i++) {
            Arrays.fill(node_id[i], -1);
        }
        total_nodes = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid1[i][j] == 'Z') {
                    special_x = i;
                    special_y = j;
                } else if (is_valid(i, j)) {
                    node_id[i][j] = ++total_nodes;
                }
            }
        }
        source_node = 0;
        sink_node = 2 * total_nodes + 1;

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (is_valid(i, j)) {
                    for (int d = 0; d < 4; d++) {
                        int x = i + directions[d][0];
                        int y = j + directions[d][1];
                        if (is_valid(x, y)) {
                            if (grid2[x][y] != 0) {
                                addEdge(node_id[i][j] + total_nodes, sink_node, grid2[x][y] - '0');
                            }
                            if (grid1[i][j] == '0') continue;
                            addEdge(source_node, node_id[i][j], grid1[i][j] - '0');
                            if (grid2[x][y] != 0) {
                                addEdge(node_id[i][j], node_id[x][y] + total_nodes, 10);
                            }
                        }
                    }
                }
            }
        }
        System.out.println(maxFlow());
        sc.close();
    }
}
